162	// evaluateConstExpr computes the result of a constant binary expression
163	func evaluateConstExpr(node *ast.Node) *ast.Node {
164		if node == nil || node.Kind != ast.NodeBinaryExpr {
165			return nil
166		}
167	
168		if len(node.Children) != 2 {
169			return nil
170		}
171	
172		left, right := node.Children[0], node.Children[1]
173		if left.Kind != ast.NodeIntLit || right.Kind != ast.NodeIntLit {
174			return nil
175		}
176	
177		leftVal := parseIntLiteral(left.Value)
178		rightVal := parseIntLiteral(right.Value)
179	
180		var result int64
181		switch node.Value {
182		case "+":
183			result = leftVal + rightVal
184		case "-":
185			result = leftVal - rightVal
186		case "*":
187			result = leftVal * rightVal
188		case "/":
189			if rightVal == 0 {
190				return nil // Don't fold division by zero
191			}
192			result = leftVal / rightVal
193		default:
194			return nil // Not a binary operator we can fold
195		}
196	
197		// Return a new constant node with the computed value
198		return &ast.Node{
199			Kind:  ast.NodeIntLit,
200			Value: formatInt(result),
201			Line:  node.Line,
202			Col:   node.Col,
203		}
204	}
205	
206	// parseIntLiteral converts a string to int64
207	func parseIntLiteral(s string) int64 {
208		var result int64
209		for _, c := range s {
210			if c >= '0' && c <= '9' {
211				result = result*10 + int64(c-'0')
212			}
213		}
214		return result
215	}
216	
217	// formatInt converts int64 back to string
218	func formatInt(n int64) string {
219		if n == 0 {
220			return "0"
221		}
222		var result string
223		neg := n < 0
224		if neg {
225			n = -n
226		}
227		for n > 0 {
228			result = string(byte(n%10)+'0') + result
229			n /= 10
230		}
231		if neg {
232			result = "-" + result
233		}
234		return result
235	}
236	
237	// DefaultRules returns all optimization rules in default order
238	func DefaultRules() []OptimizationRule {
239		return []OptimizationRule{
240			ConstantFoldingRule,
241			DeadCodeEliminationRule,
242			InliningRule,
243			LoopInvariantMovementRule,
244			CommonSubexpressionRule,
245		}
246	}
